    // 미응답 요청의 앱 대기만 해제한다. 늦은 실측은 기존 listener로 받는다.
    const timeout = setTimeout(request.fail, REFRESH_WAIT_LIMIT);
    set({ isRefreshing: true });

    return request;
  }

  return { init, cleanup, refresh };
}

/** 비React 실행 판단은 화면용 override를 사용하지 않는다. */
export const networkStore = {
  get realStatus() {
    return useNetworkStore.getState().realStatus;
  },
  get override() {
    return useNetworkStore.getState().overrideStatus;
  },
  setOverride(status: NetworkStatus | null) {
    useNetworkStore.getState().setOverride(status);
  },
  init() {
    useNetworkStore.getState().init();
  },
  cleanup() {
    useNetworkStore.getState().cleanup();
  },
  refresh() {
    return useNetworkStore.getState().refresh();
  },
};

/** 화면 표시·제한 시뮬레이션용. 실제 요청 판단에는 사용하지 않는다. */
export function useDisplayNetworkStatus(): NetworkStatus {
  return useNetworkStore((state) => state.overrideStatus ?? state.realStatus);
}

export function useRealNetworkStatus(): NetworkStatus {
  return useNetworkStore((state) => state.realStatus);
}

export function useNetworkCheck() {
  const checkStatus = useNetworkStore((state) => state.checkStatus);
  const isRefreshing = useNetworkStore((state) => state.isRefreshing);
  const refresh = useNetworkStore((state) => state.refresh);

  return { checkStatus, isRefreshing, refresh };
}

export function useNetworkControl() {
  const overrideStatus = useNetworkStore((state) => state.overrideStatus);
  const setOverride = useNetworkStore((state) => state.setOverride);

  return {
    overrideStatus,
    setOverrideOnline: () => setOverride('online'),
    setOverrideOffline: () => setOverride('offline'),
    setOverrideUnknown: () => setOverride('unknown'),
    clearOverride: () => setOverride(null),
  };
}
import { getTripActivationStatus, hasAnyActivatedTrip } from './metadata';
import { OfflineError } from './errors';
import { networkStore } from '@/shared/store/network';

interface RouteOperations<T> {
  local: () => Promise<T>;
  remote: () => Promise<T>;
}

function assertRemoteAvailable(offlineMessage: string, tripId?: string) {
  const status = networkStore.realStatus;

  if (status === 'online') {
    return;
  }

  throw new OfflineError(
    status === 'unknown' ? '인터넷 연결을 아직 확인하지 못했어요. 잠시 후 다시 시도해주세요.' : offlineMessage,
    { action: status === 'unknown' ? 'ONLINE_REQUIRED' : 'ACTIVATE_PROMPT', tripId },
  );
}

function assertWritesAllowed() {
  if (networkStore.override !== null) {
    throw new OfflineError('네트워크 화면 테스트 중에는 저장·삭제할 수 없어요. 강제 설정을 해제해주세요.', {
      action: 'ONLINE_REQUIRED',
    });
  }
}

/** Trip 조회의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripQuery<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 조회는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildQuery<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요', tripId);
  return await operations.remote();
}

/** Trip 쓰기의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripMutation<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  assertWritesAllowed();

