import React from 'react';
import { View, Text } from 'react-native';
import { Pressable } from '@repo/ui';
import { Database, Wifi, WifiOff, RotateCcw, RefreshCw, Upload } from 'lucide-react-native';
import {
  useNetworkCheck,
  useNetworkControl,
  useDisplayNetworkStatus,
  useRealNetworkStatus,
} from '@/shared/store/network';

const NETWORK_STATUS_DISPLAY = {
  online: {
    Icon: Wifi,
    color: '#228B22',
    textClassName: 'text-primary',
    label: '🟢 온라인',
  },
  offline: {
    Icon: WifiOff,
    color: '#BF4040',
    textClassName: 'text-destructive',
    label: '🔴 오프라인',
  },
  unknown: {
    Icon: Wifi,
    color: '#666',
    textClassName: 'text-muted-foreground',
    label: '⚪ 미확정',
  },
};

interface DashboardViewProps {
  stats: { pending: number; inProgress: number; failed: number; total: number } | null;
  counts: {
    trips: number;
    schedules: number;
    expenses: number;
    activations: number;
    offlineCities: number;
  };
  onRefresh: () => void;
  onManualSync: () => void;
}

export function DashboardView({ stats, counts, onRefresh, onManualSync }: DashboardViewProps) {
  const { overrideStatus, setOverrideOnline, setOverrideOffline, setOverrideUnknown, clearOverride } =
    useNetworkControl();
  const realNetworkStatus = useRealNetworkStatus();
  const displayStatus = useDisplayNetworkStatus();
  const { checkStatus, isRefreshing, refresh } = useNetworkCheck();

  const { Icon: StatusIcon, color, textClassName, label } = NETWORK_STATUS_DISPLAY[displayStatus];

  return (
    <View className='gap-md'>
      {/* Network Status Card */}
      <View className='rounded-lg bg-card p-md border border-card-border'>
        <View className='flex-row items-center gap-xs mb-sm'>
          <StatusIcon size={20} color={color} />
          <Text className='text-title-medium text-foreground'>네트워크 상태</Text>
        </View>
        <View className='gap-2xs mb-sm'>
          <Text className='text-body text-foreground'>
            현재 상태: <Text className={`${textClassName} font-semibold`}>{label}</Text>
          </Text>
          <Text className='text-label text-muted-foreground'>실제 네트워크: {realNetworkStatus}</Text>
          {overrideStatus && <Text className='text-label text-muted-foreground'>⚠️ 강제 설정: {overrideStatus}</Text>}
          {realNetworkStatus === 'unknown' && (
            <Text className='text-label text-muted-foreground'>
              {checkStatus === 'unavailable' ? '인터넷 연결을 확인할 수 없어요' : '인터넷 연결 확인 중'}
            </Text>
          )}
        </View>
        <View className='flex-row gap-xs'>
          <Pressable
            variant='outline'
            className='flex-1 flex-row items-center justify-center gap-xs py-xs rounded-lg border border-primary'
            onPress={setOverrideOnline}
          >
            <Wifi size={14} color='#228B22' />
            <Text className='text-label text-primary'>온라인</Text>
          </Pressable>
          <Pressable
            variant='outline'
            className='flex-1 flex-row items-center justify-center gap-xs py-xs rounded-lg border border-destructive'
            onPress={setOverrideOffline}
          >
            <WifiOff size={14} color='#BF4040' />
            <Text className='text-label text-destructive'>오프라인</Text>
          </Pressable>
          <Pressable variant='outline' className='flex-1 py-xs' onPress={setOverrideUnknown}>
            <Text className='text-label text-muted-foreground'>미확정</Text>
          </Pressable>
          <Pressable
            variant='outline'
            className='flex-1 flex-row items-center justify-center gap-xs py-xs rounded-lg border border-card-border'
            onPress={clearOverride}
          >
            <RotateCcw size={14} color='#666' />
            <Text className='text-label text-muted-foreground'>실제</Text>
          </Pressable>
        </View>
        <Pressable variant='outline' className='mt-sm' onPress={refresh} disabled={isRefreshing}>
          {isRefreshing ? '재확인 중...' : '실제 연결 재확인'}
        </Pressable>
      </View>

      {/* DB Stats Card */}
      <View className='rounded-lg bg-card p-md border border-card-border'>
        <View className='flex-row items-center gap-xs mb-sm'>
          <Database size={20} color='#228B22' />
          <Text className='text-title-medium text-foreground'>DB 통계</Text>
        </View>
        <View className='gap-2xs'>
          <Text className='text-body text-foreground'>여행: {counts.trips}개</Text>
          <Text className='text-body text-foreground'>일정: {counts.schedules}개</Text>
          <Text className='text-body text-foreground'>경비: {counts.expenses}개</Text>
          <Text className='text-body text-foreground'>활성화된 여행: {counts.activations}개</Text>
          <Text className='text-body text-foreground'>오프라인 지도: {counts.offlineCities}개</Text>
          {stats && (
            <>
              <Text className='text-body text-foreground'>동기화 대기: {stats.pending}개</Text>
              <Text className='text-body text-foreground'>동기화 실패: {stats.failed}개</Text>
              <Text className='text-body text-foreground'>진행 중: {stats.inProgress}개</Text>
            </>
          )}
        </View>
      </View>

      {/* Quick Actions */}
      <View className='gap-sm'>
        <Pressable
          variant='outline'
          className='flex-row items-center justify-center gap-xs py-3 rounded-lg border border-card-border'
          onPress={onRefresh}
        >
          <RefreshCw size={16} color='#228B22' />
          <Text className='text-body text-primary'>새로고침</Text>
        </Pressable>

        <Pressable
          variant='outline'
          className='flex-row items-center justify-center gap-xs py-3 rounded-lg border border-primary bg-primary/5'
          onPress={onManualSync}
        >
          <Upload size={16} color='#228B22' />
          <Text className='text-body text-primary font-semibold'>전체 동기화 (Push + Pull)</Text>
        </Pressable>
      </View>
    </View>
  );
}
/**
 * useAppPolicy Hook
 *
 * 범용 Policy Hook - 모든 Entity의 CRUD 정책을 한 번에 제공
 * 여러 Entity 정책을 동시에 체크해야 할 때 사용
 */

import { useMemo } from 'react';
import { useDisplayNetworkStatus } from '@/shared/store/network';
import { useGetTripActivation } from '@/entities/trip/data/useGetTripActivation';
import { TRIP_POLICIES, SCHEDULE_POLICIES, EXPENSE_POLICIES, SERVICE_POLICIES } from './constants';
import type { CRUDPermission, ServiceConfig, PolicyKey, ActivationStatus } from './types';

/**
 * App Policy Context
 *
 * 모든 Entity의 CRUD 정책 + Service 설정
 */
export interface AppPolicyContext {
  trip: {
    create: CRUDPermission;
    read: CRUDPermission;
    update: CRUDPermission;
    delete: CRUDPermission;
  };
  schedule: {
    create: CRUDPermission;
    read: CRUDPermission;
    update: CRUDPermission;
    delete: CRUDPermission;
  };
  expense: {
    create: CRUDPermission;
    read: CRUDPermission;
    update: CRUDPermission;
    delete: CRUDPermission;
  };
  service: ServiceConfig;
}

/**
 * 앱 전역 Policy Hook
 *
 * @param tripId - Trip ID (optional)
 * @returns 모든 Entity의 CRUD 정책
 *
 * @example
 * ```tsx
 * // 여러 Entity 정책을 동시에 체크
 * const policy = useAppPolicy(tripId);
 *
 * if (!policy.schedule.create.allowed) {
 *   return <DisabledMessage reason={policy.schedule.create.reason} />;
 * }
 *
 * if (policy.expense.create.mode === 'manual-only') {
 *   return <ManualInputForm />;
 * }
 *
 * // Service 설정도 접근 가능
 * if (policy.service.mapProvider === 'mapbox') {
 *   return <OfflineMap />;
 * }
 * ```
 */
export function useAppPolicy(tripId?: string): AppPolicyContext {
  const networkStatus = useDisplayNetworkStatus();

  const { data: activation } = useGetTripActivation(tripId ?? '');

  const isActivated = activation?.isActivated ?? false;
  const activationStatus: ActivationStatus = tripId && isActivated ? 'active' : 'inactive';

  // unknown도 Remote 기능을 열지 않는다. 현재 4-state 권한 표의 제한 모드를 재사용한다.
  const policyNetworkStatus = networkStatus === 'online' ? 'online' : 'offline';
  const policyKey: PolicyKey = `${policyNetworkStatus}_${activationStatus}`;

  return useMemo(
    () => ({
      trip: {
        create: TRIP_POLICIES.create[policyKey],
        read: TRIP_POLICIES.read[policyKey],
        update: TRIP_POLICIES.update[policyKey],
        delete: TRIP_POLICIES.delete[policyKey],
      },
      schedule: {
        create: SCHEDULE_POLICIES.create[policyKey],
        read: SCHEDULE_POLICIES.read[policyKey],
        update: SCHEDULE_POLICIES.update[policyKey],
        delete: SCHEDULE_POLICIES.delete[policyKey],
      },
      expense: {
        create: EXPENSE_POLICIES.create[policyKey],
        read: EXPENSE_POLICIES.read[policyKey],
        update: EXPENSE_POLICIES.update[policyKey],
        delete: EXPENSE_POLICIES.delete[policyKey],
      },
      service: SERVICE_POLICIES[policyKey],
    }),
    [policyKey],
  );
}
/**
 * Policy Layer Types (CRUD-Centric)
 *
 * 동작 중심 구조로 4-state policy matrix 정의
 * - online_active: 온라인 + 활성화 (전체 기능)
 * - online_inactive: 온라인 + 비활성 (서버 직접 접근)
 * - offline_active: 오프라인 + 활성화 (수동 입력 모드)
 * - offline_inactive: 오프라인 + 비활성 (읽기 전용)
 */

import type { NetworkStatus } from '@/shared/store/network';

export type { NetworkStatus } from '@/shared/store/network';
export type ActivationStatus = 'active' | 'inactive';

// 실제 관측은 세 상태이며, 기존 권한 표는 unknown의 제한 모드를 offline과 공유한다.
export type PolicyKey = `${Exclude<NetworkStatus, 'unknown'>}_${ActivationStatus}`;

/**
 * CRUD Operation Mode
 *
 * - full: 전체 기능 사용 가능
 * - manual-only: 수동 입력만 가능 (API 호출 없이 텍스트만)
 * - limited: 일부 필드만 수정 가능
 */
export type CRUDMode = 'full' | 'manual-only' | 'limited';

/**
 * CRUD Permission
 */
export interface CRUDPermission {
  allowed: boolean;
  mode?: CRUDMode;
  reason?: string; // 비활성화된 경우 사용자에게 보여줄 이유

  // 필드별 검증 규칙 (optional)
  validation?: {
    required?: string[]; // 필수 필드
    optional?: string[]; // 선택 필드
    allowed?: string[]; // 허용된 필드 (limited mode)
    blocked?: string[]; // 차단된 필드 (limited mode)
    enforced?: Record<string, unknown>; // 강제 값 (e.g., latitude: null)
  };
}

/**
 * CRUD Operation Policies
 *
 * 각 CRUD 동작이 4가지 상태에서 어떻게 동작하는지 정의
 */
export interface CRUDOperationPolicies {
  create: Record<PolicyKey, CRUDPermission>;
  read: Record<PolicyKey, CRUDPermission>;
  update: Record<PolicyKey, CRUDPermission>;
  delete: Record<PolicyKey, CRUDPermission>;
}

export type TripPolicies = CRUDOperationPolicies;
export type SchedulePolicies = CRUDOperationPolicies;
export type ExpensePolicies = CRUDOperationPolicies;

/**
 * Service Layer Configuration
 *
 * 서비스 레이어는 상태별 설정 (기존 구조 유지)
 */
export interface ServiceConfig {
  mapProvider: 'google' | 'mapbox' | 'none';
  searchMode: 'api' | 'cache' | 'disabled';
  syncStrategy: 'immediate' | 'background' | 'manual' | 'disabled';
  uiMode: 'full' | 'limited' | 'readonly';
}

/**
 * Service Layer Policies
 */
export type ServicePolicies = Record<PolicyKey, ServiceConfig>;
import { View, Text } from 'react-native';
import { Wifi, WifiOff } from 'lucide-react-native';
import { useDisplayNetworkStatus } from '@/shared/store/network';

/**
 * 네트워크 상태 인디케이터 (헤더 우측)
 * - 온라인: 초록색 Wifi 아이콘 + "온라인"
 * - 오프라인: 빨간색 WifiOff 아이콘 + "오프라인"
 * - 알 수 없음: 회색 Wifi 아이콘 + "확인 중"
 */
export function NetworkStatusIndicator() {
  const networkStatus = useDisplayNetworkStatus();

  if (networkStatus === 'online') {
    return (
      <View className='flex-row items-center'>
        <Wifi size={14} color='hsl(140, 65%, 45%)' />
        <Text className='text-label text-status-online ml-1'>온라인</Text>
      </View>
    );
  }

  if (networkStatus === 'offline') {
    return (
      <View className='flex-row items-center'>
        <WifiOff size={14} color='hsl(0, 84%, 60%)' />
