    expect(useNetworkStore.getState().isRefreshing).toBe(false);
    expect(jest.getTimerCount()).toBe(0);
  });

  it('cleanup은 진행 중 확인을 해제하고 이전 확인 결과는 재초기화에 반영하지 않는다', async () => {
