 */
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // 로컬 DB 조회는 staleTime을 길게 설정
      staleTime: 5 * 60 * 1000, // 5분
      gcTime: 10 * 60 * 1000, // 10분
      retry: 1,
      refetchOnWindowFocus: false,
      refetchOnReconnect: false, // SyncProvider가 처리
