import React, { useState } from 'react';
import { View, ScrollView, RefreshControl, Alert } from 'react-native';
import { MobileHeader, Container, Stack } from '@/shared/components';
import { ArrowLeft } from 'lucide-react-native';
import { router } from 'expo-router';
import MapboxGL from '@rnmapbox/maps';
import { db, trips, schedules, expenses, syncQueue, offlineCities, tripActivations } from '@/shared/db';
import type { Trip, Schedule, Expense, SyncQueueItem, OfflineCity, TripActivation } from '@/shared/db/schema';
import { resetDatabase } from '@/shared/db';
import { getSyncQueueStats } from '@/shared/services/sync/queue';
import { triggerSync } from '@/shared/services/sync/engine';
import { DashboardView } from './DashboardView';
import { DataInspectorView } from './DataInspectorView';
import { ToolsView } from './ToolsView';
import { Pressable } from '@repo/ui';
import { Text } from 'react-native';

type ViewMode = 'dashboard' | 'inspector' | 'tools';

export default function DebugScreen() {
  const [refreshing, setRefreshing] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('dashboard');

  // Data States
  const [tripsData, setTripsData] = useState<Trip[]>([]);
  const [schedulesData, setSchedulesData] = useState<Schedule[]>([]);
  const [expensesData, setExpensesData] = useState<Expense[]>([]);
  const [offlineCitiesData, setOfflineCitiesData] = useState<OfflineCity[]>([]);
  const [syncQueueData, setSyncQueueData] = useState<SyncQueueItem[]>([]);
  const [tripActivationsData, setTripActivationsData] = useState<TripActivation[]>([]);
  const [stats, setStats] = useState<{ pending: number; inProgress: number; failed: number; total: number } | null>(
    null,
  );

  const loadData = async () => {
    try {
      setRefreshing(true);

      const tripsResult = await db.select().from(trips).all();
      setTripsData(tripsResult);

      const schedulesResult = await db.select().from(schedules).all();
      setSchedulesData(schedulesResult);

      const expensesResult = await db.select().from(expenses).all();
      setExpensesData(expensesResult);

      const offlineCitiesResult = await db.select().from(offlineCities).all();
      setOfflineCitiesData(offlineCitiesResult);

      const syncQueueResult = await db.select().from(syncQueue).all();
      setSyncQueueData(syncQueueResult);

      const tripActivationsResult = await db.select().from(tripActivations).all();
      setTripActivationsData(tripActivationsResult);

      const statsResult = await getSyncQueueStats();
      setStats(statsResult);

      console.log('✅ Debug data loaded');
    } catch (error) {
      console.error('❌ Failed to load debug data:', error);
      Alert.alert('오류', '데이터를 불러올 수 없습니다.');
    } finally {
      setRefreshing(false);
    }
  };

  const handleResetDatabase = () => {
    Alert.alert('⚠️ DB 초기화', '모든 로컬 데이터가 삭제됩니다.\n계속하시겠습니까?', [
      { text: '취소', style: 'cancel' },
      {
        text: '초기화',
        style: 'destructive',
        onPress: async () => {
          try {
            await resetDatabase();
            await loadData();
            Alert.alert('✅ 성공', 'DB가 초기화되었습니다.');
          } catch (error) {
            console.error('❌ Failed to reset DB:', error);
            Alert.alert('❌ 실패', 'DB 초기화에 실패했습니다.');
          }
        },
      },
    ]);
  };

  const handleClearOfflineMaps = () => {
    Alert.alert(
      '⚠️ 오프라인 지도 완전 삭제',
      'Mapbox 네이티브 오프라인 팩과 DB의 offlineCities 레코드를 모두 삭제합니다.\n계속하시겠습니까?',
      [
        { text: '취소', style: 'cancel' },
        {
          text: '삭제',
          style: 'destructive',
          onPress: async () => {
            try {
              // 1. Mapbox 네이티브 오프라인 팩 삭제
              const packs = await MapboxGL.offlineManager.getPacks();
              console.log(`🗑️ Deleting ${packs.length} offline packs...`);

              for (const pack of packs) {
                await MapboxGL.offlineManager.deletePack(pack.name);
                console.log(`✅ Deleted pack: ${pack.name}`);
              }

              // 2. DB의 offlineCities 테이블 비우기
              await db.delete(offlineCities);
              console.log('✅ Cleared offlineCities table');

              await loadData();
              Alert.alert('✅ 성공', `${packs.length}개의 오프라인 지도와 DB 레코드를 모두 삭제했습니다.`);
            } catch (error) {
              console.error('❌ Failed to clear offline maps:', error);
              Alert.alert('❌ 실패', '오프라인 지도 삭제에 실패했습니다.');
            }
          },
        },
      ],
    );
  };

  const handleManualSync = async () => {
    try {
      const result = await triggerSync();

      if (result.success) {
        await loadData(); // 데이터 새로고침
        Alert.alert('✅ 성공', result.message);
      } else {
        Alert.alert('❌ 실패', result.message);
      }
    } catch (error) {
      console.error('❌ Manual sync error:', error);
      Alert.alert('❌ 오류', '동기화 중 오류가 발생했습니다.');
    }
  };

  const handleManualActivate = async (tripId: string, tripName: string) => {
    Alert.alert('🟢 수동 활성화', `"${tripName}" 여행을 활성화하시겠습니까?`, [
      { text: '취소', style: 'cancel' },
      {
        text: '활성화',
        onPress: async () => {
          try {
            const { generateId } = await import('@/shared/services/id/ulid');
            const { getCurrentISOString } = await import('@/shared/db/utils');
            const { eq } = await import('drizzle-orm');

            const now = getCurrentISOString();
            const trip = tripsData.find((t) => t.id === tripId);

            if (!trip) {
              Alert.alert('❌ 오류', '여행을 찾을 수 없습니다.');
              return;
            }

            // 기존 활성화 확인
            const existing = await db.select().from(tripActivations).where(eq(tripActivations.tripId, tripId)).get();

            if (existing) {
              // 이미 활성화 레코드가 있으면 업데이트
              await db
                .update(tripActivations)
                .set({
                  isActivated: true,
                  activatedAt: now,
                  deactivatedAt: null,
                  updatedAt: now,
                })
                .where(eq(tripActivations.tripId, tripId));
            } else {
              // 새 활성화 레코드 생성
              const expiresAt = new Date(trip.endDate);
              expiresAt.setDate(expiresAt.getDate() + 7);

              await db.insert(tripActivations).values({
                id: generateId(),
                tripId,
                userId: trip.userId,
                isActivated: true,
                activatedAt: now,
                expiresAt: expiresAt.toISOString(),
                syncStatus: 'PENDING',
                createdAt: now,
                updatedAt: now,
              });
            }

            await loadData();
            Alert.alert('✅ 성공', `"${tripName}" 여행이 활성화되었습니다.`);
          } catch (error) {
            console.error('❌ Failed to activate trip:', error);
            Alert.alert('❌ 실패', '활성화에 실패했습니다.');
          }
        },
      },
    ]);
  };

  const handleManualDeactivate = async (tripId: string, tripName: string) => {
    Alert.alert('🔴 수동 비활성화', `"${tripName}" 여행을 비활성화하시겠습니까?`, [
      { text: '취소', style: 'cancel' },
      {
        text: '비활성화',
        style: 'destructive',
        onPress: async () => {
          try {
            const { getCurrentISOString } = await import('@/shared/db/utils');
            const { eq } = await import('drizzle-orm');

            const now = getCurrentISOString();

            await db
              .update(tripActivations)
              .set({
                isActivated: false,
                deactivatedAt: now,
                updatedAt: now,
              })
              .where(eq(tripActivations.tripId, tripId));

            await loadData();
            Alert.alert('✅ 성공', `"${tripName}" 여행이 비활성화되었습니다.`);
          } catch (error) {
            console.error('❌ Failed to deactivate trip:', error);
            Alert.alert('❌ 실패', '비활성화에 실패했습니다.');
          }
        },
      },
    ]);
  };

  const handleClearAllActivations = () => {
    Alert.alert(
      '⚠️ 활성화 데이터 완전 삭제',
      'tripActivations 테이블과 모든 로컬 여행 데이터(trips, schedules, expenses)를 삭제합니다.\n계속하시겠습니까?',
      [
        { text: '취소', style: 'cancel' },
        {
          text: '초기화',
          style: 'destructive',
          onPress: async () => {
            try {
              // 1. tripActivations 테이블 비우기
              await db.delete(tripActivations);
              console.log('✅ Cleared tripActivations table');

              // 2. 로컬 여행 데이터 삭제
              await db.delete(trips);
              console.log('✅ Cleared trips table');

              await db.delete(schedules);
              console.log('✅ Cleared schedules table');

              await db.delete(expenses);
              console.log('✅ Cleared expenses table');

              await loadData();
              Alert.alert('✅ 성공', '모든 활성화 정보와 로컬 여행 데이터가 삭제되었습니다.');
            } catch (error) {
              console.error('❌ Failed to clear activations:', error);
              Alert.alert('❌ 실패', '초기화에 실패했습니다.');
            }
          },
        },
      ],
    );
  };

  React.useEffect(() => {
    loadData();
  }, []);

  return (
    <View className='flex-1 bg-background'>
      <MobileHeader
        title='디버그 콘솔'
        leftIcon={<ArrowLeft size={20} color='#1F1F1F' />}
        onLeftPress={() => router.back()}
      />

      <View className='px-md py-sm bg-background'>
        <View className='flex-row p-1 bg-muted rounded-lg'>
          {(['dashboard', 'inspector', 'tools'] as const).map((mode) => (
            <Pressable
              key={mode}
              variant='ghost'
              className={`flex-1 py-xs items-center rounded-md ${
                viewMode === mode ? 'bg-background shadow-sm' : 'bg-transparent'
              }`}
              onPress={() => setViewMode(mode)}
            >
              <Text
                className={`text-label font-semibold ${
                  viewMode === mode ? 'text-foreground' : 'text-muted-foreground'
                }`}
              >
                {mode === 'dashboard' ? '대시보드' : mode === 'inspector' ? '데이터' : '도구'}
              </Text>
            </Pressable>
          ))}
        </View>
      </View>

      <ScrollView className='flex-1' refreshControl={<RefreshControl refreshing={refreshing} onRefresh={loadData} />}>
        <Container>
          <Stack direction='vertical' gap='md' className='py-sm'>
            {viewMode === 'dashboard' && (
              <DashboardView
                stats={stats}
                counts={{
                  trips: tripsData.length,
                  schedules: schedulesData.length,
                  expenses: expensesData.length,
                  activations: tripActivationsData.filter((a) => a.isActivated).length,
                  offlineCities: offlineCitiesData.length,
                }}
                onRefresh={loadData}
                onManualSync={handleManualSync}
              />
            )}
            {viewMode === 'inspector' && (
              <DataInspectorView
                data={{
                  trips: tripsData,
                  schedules: schedulesData,
                  expenses: expensesData,
                  activations: tripActivationsData,
                  offlineCities: offlineCitiesData,
                  syncQueue: syncQueueData,
                }}
                onActivateTrip={handleManualActivate}
                onDeactivateTrip={handleManualDeactivate}
              />
            )}
            {viewMode === 'tools' && (
              <ToolsView
                onResetDatabase={handleResetDatabase}
                onClearOfflineMaps={handleClearOfflineMaps}
                onClearActivations={handleClearAllActivations}
              />
            )}
          </Stack>
        </Container>
      </ScrollView>
    </View>
  );
}
import axios, { type AxiosInstance, type AxiosError } from 'axios';
import { EXPO_PUBLIC_API_URL } from '@env';
import { getAccessToken, AuthRequiredError } from '@/shared/services/auth';
import { authStore } from '@/shared/store/auth';

/**
 * 동기화 전용 Axios 클라이언트
 *
 * 특징:
 * - sync_queue 작업을 서버로 전송하는 전용 클라이언트
 * - 5xx 에러 시 자동 재시도 (최대 3회)
 * - Exponential Backoff: 2초, 4초, 8초
 * - 네트워크 에러는 재시도하지 않음 (오프라인 상태)
 */

const syncApiClient: AxiosInstance = axios.create({
  baseURL: EXPO_PUBLIC_API_URL,
  timeout: 15000, // 15초 (일반 API보다 여유 있게)
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * Request Interceptor
 * - 인증 토큰 자동 추가
 */
syncApiClient.interceptors.request.use(
  async (config) => {
    const token = await getAccessToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    console.log(`🔄 [Sync API] ${config.method?.toUpperCase()} ${config.url}`);

    return config;
  },
  (error) => {
    console.error('❌ [Sync API] Request error:', error);
    return Promise.reject(error);
  },
);

/**
 * Response Interceptor
 * - 자동 재시도 로직 (5xx 에러)
 * - Exponential Backoff
 */
syncApiClient.interceptors.response.use(
  (response) => {
    console.log(`✅ [Sync API] Success:`, response.status);
    return response;
  },
  async (error: AxiosError) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const originalRequest = error.config as any;

    // 401 인증 에러 → AuthRequiredError로 변환 (sync engine에서 PENDING 유지)
    if (error.response?.status === 401) {
      console.warn('🔐 [Sync API] 401 Unauthorized, throwing AuthRequiredError');
      authStore.setSessionExpired(true);
      return Promise.reject(new AuthRequiredError('동기화 인증 실패'));
    }

    // 재시도 가능 여부 판단
    const shouldRetry = error.response?.status && error.response.status >= 500 && error.response.status < 600; // 5xx 에러만 재시도

    // 네트워크 에러는 재시도하지 않음 (오프라인 상태)
    if (error.code === 'ERR_NETWORK' || error.message === 'Network Error') {
      console.warn('⚠️ [Sync API] Network error, not retrying (offline)');
      return Promise.reject(error);
    }

    // 재시도 로직
    if (shouldRetry && !originalRequest._retry) {
      originalRequest._retry = true;
      originalRequest._retryCount = (originalRequest._retryCount || 0) + 1;

      // 최대 3회 재시도
      if (originalRequest._retryCount <= 3) {
        // Exponential Backoff: 2초, 4초, 8초
        const delay = 2000 * Math.pow(2, originalRequest._retryCount - 1);

        console.log(`🔄 [Sync API] Retrying (${originalRequest._retryCount}/3) after ${delay}ms...`);

        // 지연 후 재시도
        await new Promise((resolve) => setTimeout(resolve, delay));

        return syncApiClient(originalRequest);
      } else {
        console.error('❌ [Sync API] Max retries reached (3)');
      }
    }

    // 재시도 불가 또는 실패
    console.error(`❌ [Sync API] Error:`, error.response?.status, error.response?.data || error.message);

    return Promise.reject(error);
  },
);

export default syncApiClient;

/**
 * 동기화 API 엔드포인트
 */
export const syncApiEndpoints = {
  /**
   * Push: 로컬 변경사항을 서버로 전송
   */
  push: '/api/sync/push',

  /**
   * Pull: 서버 변경사항을 로컬로 가져오기 (Phase 2에서 구현)
   */
  pull: '/api/sync/pull',
};
import { create } from 'zustand';
import {
  getAuthData,
  saveAuthData,
  updateTokens,
  clearAuthData,
  hasAuthData,
  type UserInfo,
} from '../services/auth/token-storage';

// ========================================
// Types
// ========================================

interface AuthState {
  // State
  userId: string | null;
  userInfo: UserInfo | null;
  isAuthenticated: boolean;
  isSessionExpired: boolean;
  isInitialized: boolean;

  // Actions
  init: () => Promise<void>;
  login: (data: { accessToken: string; refreshToken: string; userId: string; userInfo?: UserInfo }) => Promise<void>;
  logout: () => Promise<void>;
  refreshTokens: (data: { accessToken: string; refreshToken: string }) => Promise<void>;
  setSessionExpired: (expired: boolean) => void;
}

// ========================================
// Store
// ========================================

export const useAuthStore = create<AuthState>((set, get) => ({
  // Initial State
  userId: null,
  userInfo: null,
  isAuthenticated: false,
  isSessionExpired: false,
  isInitialized: false,

  /**
   * 앱 시작 시 SecureStore에서 인증 데이터 복원
   * - 토큰 존재 여부만 확인 (만료 무시 - 오프라인 지원)
   * - user 정보도 함께 복원 (오프라인에서 프로필 표시)
   */
  init: async () => {
    if (get().isInitialized) return;

    try {
      const { userId, accessToken, userInfo } = await getAuthData();

      if (userId && accessToken) {
        console.log('🔐 [AuthStore] Restored auth from SecureStore');
        set({
          userId,
          userInfo,
          isAuthenticated: true,
          isSessionExpired: false,
          isInitialized: true,
        });
      } else {
        console.log('🔐 [AuthStore] No auth data found');
        set({
          userId: null,
          userInfo: null,
          isAuthenticated: false,
          isSessionExpired: false,
          isInitialized: true,
        });
      }
    } catch (error) {
      console.error('🔐 [AuthStore] Failed to restore auth:', error);
      set({
        userId: null,
        userInfo: null,
        isAuthenticated: false,
        isSessionExpired: false,
        isInitialized: true,
      });
    }
  },

  /**
   * 로그인 성공 시 토큰 + user 정보 저장 + 상태 업데이트
   */
  login: async (data) => {
    await saveAuthData(data);
    console.log('🔐 [AuthStore] Login successful');
    set({
      userId: data.userId,
      userInfo: data.userInfo ?? null,
      isAuthenticated: true,
      isSessionExpired: false,
    });
  },

  /**
   * 로그아웃 시 토큰 + user 정보 삭제 + 상태 초기화
   */
  logout: async () => {
    await clearAuthData();
    console.log('🔐 [AuthStore] Logout completed');
    set({
      userId: null,
      userInfo: null,
      isAuthenticated: false,
      isSessionExpired: false,
    });
  },

  /**
   * 토큰 갱신 성공 시 새 토큰 저장
   */
  refreshTokens: async (data) => {
    await updateTokens(data);
    console.log('🔐 [AuthStore] Tokens refreshed');
    set({
      isSessionExpired: false,
    });
  },

  /**
   * 세션 만료 상태 설정
   * - 401 에러 + refresh 실패 시 true로 설정
   * - 재로그인 성공 시 false로 복구
   */
  setSessionExpired: (expired) => {
    console.log(`🔐 [AuthStore] Session expired: ${expired}`);
    set({ isSessionExpired: expired });
  },
}));

// ========================================
// Non-React Access Helper
// ========================================

/**
 * 비-React 환경(일반 함수 등)에서 상태 접근을 위한 헬퍼
 */
export const authStore = {
  get userId() {
    return useAuthStore.getState().userId;
  },
  get userInfo() {
    return useAuthStore.getState().userInfo;
  },
  get isAuthenticated() {
    return useAuthStore.getState().isAuthenticated;
  },
  get isSessionExpired() {
    return useAuthStore.getState().isSessionExpired;
  },
  get isInitialized() {
    return useAuthStore.getState().isInitialized;
  },
  async init() {
    await useAuthStore.getState().init();
  },
  async login(data: { accessToken: string; refreshToken: string; userId: string; userInfo?: UserInfo }) {
    await useAuthStore.getState().login(data);
  },
  async logout() {
    await useAuthStore.getState().logout();
  },
  async refreshTokens(data: { accessToken: string; refreshToken: string }) {
    await useAuthStore.getState().refreshTokens(data);
  },
