/**
 * Policy Error
 *
 * Policy 규칙 위반 시 발생하는 에러
 */

import type { CRUDPermission } from './types';

export class PolicyError extends Error {
  public readonly code: string;
  public readonly permission: CRUDPermission;
  public readonly action?: string;

  constructor(
    message: string,
    options?: {
      permission?: CRUDPermission;
      action?: string;
      code?: string;
    },
  ) {
    super(message);
    this.name = 'PolicyError';
    this.code = options?.code || 'POLICY_VIOLATION';
    this.permission = options?.permission || { allowed: false };
    this.action = options?.action;

    // Maintains proper stack trace for where our error was thrown (only available on V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, PolicyError);
    }
  }
}

/**
 * Policy Error 생성 헬퍼
 */
export function createPolicyError(operation: string, permission: CRUDPermission): PolicyError {
  return new PolicyError(permission.reason || `${operation} is not allowed`, {
    permission,
    code: `POLICY_${operation.toUpperCase()}_DENIED`,
  });
}
/**
 * Mapbox Directions API 서비스
 * - 실제 도로 경로 계산
 * - polyline6 압축 형식으로 응답
 * - 오프라인 지도용 경로 데이터 제공
 */

// Mapbox 교통수단 프로필
export type MapboxProfile = 'walking' | 'cycling' | 'driving-traffic';

// 좌표 타입
export interface Coordinate {
  latitude: number;
  longitude: number;
}

// Directions API 응답
export interface DirectionsResponse {
  geometry: string; // polyline6 압축 문자열
  distance: number; // 미터 (meters)
  duration: number; // 초 (seconds)
}

/**
 * Mapbox Directions API 호출
 * @param from - 출발 좌표
 * @param to - 도착 좌표
 * @param profile - 교통수단 (기본: walking)
 * @returns 경로 데이터 (geometry, distance, duration)
 */
export async function getDirections({
  from,
  to,
  profile = 'walking',
}: {
  from: Coordinate;
  to: Coordinate;
  profile?: MapboxProfile;
}): Promise<DirectionsResponse> {
  const accessToken = process.env.EXPO_PUBLIC_MAPBOX_PUBLIC_ACCESS_TOKEN;

  if (!accessToken) {
    throw new Error('❌ EXPO_PUBLIC_MAPBOX_PUBLIC_ACCESS_TOKEN not found');
  }

  // Mapbox Directions API URL
  // 형식: /directions/v5/{profile}/{coordinates}
  const url = `https://api.mapbox.com/directions/v5/mapbox/${profile}/${from.longitude},${from.latitude};${to.longitude},${to.latitude}?access_token=${accessToken}&geometries=polyline6&overview=full`;

  try {
    console.log(`🛣️ Fetching route (${profile}): ${from.latitude},${from.longitude} → ${to.latitude},${to.longitude}`);

    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

