  // 지도 영역 자동 조정 (react-native-maps - Google Maps 모드에서만)
  useEffect(() => {
    if (mapRef.current && policy.service.mapProvider === 'google') {
      if (selectedLocation) {
        // 선택된 장소로 포커스
        mapRef.current.animateToRegion({
          latitude: selectedLocation.latitude,
          longitude: selectedLocation.longitude,
          latitudeDelta: 0.01,
          longitudeDelta: 0.01,
        });
