            </Text>
          </View>
        </LinearGradient>
      );

    case 'google':
    default:
      // Google Maps 사용 (react-native-maps)
      console.log('🌐 Using Google Maps (online)');
      return (
        <View style={styles.map}>
          <RNMapView
            ref={mapRef}
            provider={PROVIDER_GOOGLE}
            style={styles.map}
            initialRegion={{
              latitude: centerLocation.latitude,
              longitude: centerLocation.longitude,
