                pinColor='#228B22'
              />
            )}

            {/* 검색 결과 마커들 (선택 전) */}
            {!selectedLocation &&
              locations.map((location, index) => (
                <Marker
                  key={`${location.latitude}-${location.longitude}-${index}`}
