/**
 * MapUnavailableView - 지도를 사용할 수 없을 때 표시되는 뷰
 *
 * 사용 시나리오:
 * - offline_inactive: 오프라인 상태에서 비활성화된 여행
 * - 네트워크 오류 등으로 지도를 로드할 수 없을 때
 */

import { View, Text, StyleSheet } from 'react-native';
import { MapIcon } from 'lucide-react-native';

interface MapUnavailableViewProps {
  message: string;
  hint?: string;
}

export function MapUnavailableView({
  message,
  hint = '네트워크에 연결하거나 여행을 활성화해주세요',
}: MapUnavailableViewProps) {
  return (
    <View style={styles.container}>
      <MapIcon size={48} color='#999' />
      <Text style={styles.message}>{message}</Text>
      <Text style={styles.hint}>{hint}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#f5f5f5',
    padding: 24,
  },
  message: {
    marginTop: 16,
    fontSize: 16,
    color: '#666',
    textAlign: 'center',
  },
  hint: {
    marginTop: 8,
    fontSize: 14,
    color: '#999',
    textAlign: 'center',
  },
});
/**
 * OfflineMapView Component
 * Mapbox 오프라인 지도 렌더링
 */

import { View, StyleSheet } from 'react-native';
import { useEffect, useRef, useMemo } from 'react';
import MapboxGL from '@rnmapbox/maps';

interface Location {
  latitude: number;
  longitude: number;
  name: string;
  address: string;
}

interface OfflineMapViewProps {
  locations: Location[];
  selectedLocation: Location | null;
  cityId: number;
}

const styles = StyleSheet.create({
  map: {
    flex: 1,
  },
});

/**
 * Mapbox 오프라인 지도 컴포넌트
 * - 오프라인 팩이 다운로드된 경우 사용
 * - react-native-maps와 동일한 props 인터페이스 제공
 */
export function OfflineMapView({ locations, selectedLocation, cityId }: OfflineMapViewProps) {
  const cameraRef = useRef<MapboxGL.Camera>(null);

  // 지도 중심 좌표
  const centerLocation = selectedLocation || locations[0];

  // 초기 카메라 설정 계산
  const initialCamera = useMemo(() => {
    if (!centerLocation) return undefined;

    if (locations.length === 1 || selectedLocation) {
      // 단일 장소 또는 선택된 장소
      const center = selectedLocation || locations[0];
      return {
        centerCoordinate: [center.longitude, center.latitude] as [number, number],
        zoomLevel: 14,
      };
    }

    // 여러 검색 결과 - bounds 계산
    const coordinates = locations.map((loc) => [loc.longitude, loc.latitude]);
    const lngs = coordinates.map((c) => c[0]);
    const lats = coordinates.map((c) => c[1]);

    return {
      bounds: {
        ne: [Math.max(...lngs), Math.max(...lats)] as [number, number],
        sw: [Math.min(...lngs), Math.min(...lats)] as [number, number],
        paddingTop: 50,
        paddingRight: 50,
        paddingBottom: 50,
        paddingLeft: 50,
      },
    };
  }, [locations, selectedLocation, centerLocation]);

  // 지도 카메라 자동 조정
  useEffect(() => {
    if (!cameraRef.current) return;

    if (selectedLocation) {
      // 선택된 장소로 포커스
      cameraRef.current.setCamera({
        centerCoordinate: [selectedLocation.longitude, selectedLocation.latitude],
        zoomLevel: 14,
        animationDuration: 0, // 애니메이션 짧게
      });
    } else if (locations.length > 0) {
      // 여러 검색 결과가 있으면 모두 보이도록
      const coordinates = locations.map((loc) => [loc.longitude, loc.latitude] as [number, number]);

      cameraRef.current.fitBounds(
        [Math.min(...coordinates.map((c) => c[0])), Math.min(...coordinates.map((c) => c[1]))],
        [Math.max(...coordinates.map((c) => c[0])), Math.max(...coordinates.map((c) => c[1]))],
        [50, 50, 50, 50], // edgePadding
        0, // 애니메이션 짧게
      );
    }
  }, [locations, selectedLocation]);

  if (!centerLocation) {
    return <View style={styles.map} />;
  }

  return (
    <View style={styles.map}>
      <MapboxGL.MapView style={styles.map} styleURL={MapboxGL.StyleURL.Street}>
        <MapboxGL.Camera ref={cameraRef} {...initialCamera} animationDuration={0} />

        <MapboxGL.UserLocation visible={true} showsUserHeadingIndicator={true} />

        {/* 선택된 장소 마커 */}
        {selectedLocation && (
          <MapboxGL.PointAnnotation
            id={`selected-${selectedLocation.latitude}-${selectedLocation.longitude}`}
            coordinate={[selectedLocation.longitude, selectedLocation.latitude]}
            title={selectedLocation.name}
            snippet={selectedLocation.address}
          >
            <View
              style={{
                width: 30,
                height: 30,
                borderRadius: 15,
                backgroundColor: '#228B22',
                borderWidth: 3,
                borderColor: '#ffffff',
              }}
            />
          </MapboxGL.PointAnnotation>
        )}

        {/* 검색 결과 마커들 (선택 전) */}
        {!selectedLocation &&
          locations.map((location, index) => (
            <MapboxGL.PointAnnotation
              key={`marker-${location.latitude}-${location.longitude}-${index}`}
              id={`marker-${location.latitude}-${location.longitude}-${index}`}
              coordinate={[location.longitude, location.latitude]}
              title={location.name}
              snippet={location.address}
            >
              <View
                style={{
                  width: 24,
                  height: 24,
                  borderRadius: 12,
                  backgroundColor: '#228B22',
                  borderWidth: 2,
                  borderColor: '#ffffff',
                }}
              />
            </MapboxGL.PointAnnotation>
          ))}
      </MapboxGL.MapView>
    </View>
  );
}
import { useState, useEffect } from 'react';

export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

