        <MobileHeader
          title='경비 상세'
          leftIcon={<ChevronLeft size={24} color='hsl(0, 0%, 12%)' />}
          onLeftPress={() => router.back()}
        />
        <View className='flex-1 items-center justify-center'>
          <ActivityIndicator size='large' color='hsl(120, 61%, 34%)' />
        </View>
      </View>
    );
