import { View, Text, StyleSheet } from 'react-native';
import { Search, WifiOff } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { useEffect, useRef } from 'react';
import RNMapView, { Marker, PROVIDER_GOOGLE } from 'react-native-maps';

import { useOfflineCity } from '@/entities/offline-city';
import { useAppPolicy } from '@/shared/policy';
import { OfflineMapView } from './OfflineMapView';
import { useMyLocation } from '@/shared/hooks/map/useMyLocation';
import { MyLocationButton } from '@/shared/components/Map/MyLocationButton';
import { MapUnavailableView } from '@/shared/components/Map/MapUnavailableView';
import { useRealNetworkStatus } from '@/shared/store/network';
import { getOnlineServicePermission } from '@/shared/services/network-access';

interface Location {
  latitude: number;
  longitude: number;
  name: string;
  address: string;
}

interface SmartMapViewProps {
  tripId: string | null;
  locations: Location[];
  selectedLocation: Location | null;
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 32,
  },
  map: {
    flex: 1,
    width: '100%',
  },
});

/**
 * 스마트 지도 컴포넌트
 *
 * 동작 (Policy-Driven):
 * 1. policy.service.mapProvider로 지도 제공자 결정
 *    - 'google': Google Maps (온라인)
 *    - 'mapbox': Mapbox (오프라인 지도)
 *    - 'none': 지도 사용 불가 (offline_inactive)
 * 2. 빈 상태면 검색 유도 UI
 */
export function PolicyBasedMapView({ tripId, locations, selectedLocation }: SmartMapViewProps) {
  const mapRef = useRef<RNMapView>(null);

  // Policy Layer로 지도 제공자 결정
  const policy = useAppPolicy(tripId ?? undefined);
  const permission = getOnlineServicePermission(useRealNetworkStatus());

  // 오프라인 지도 조회 (mapbox 모드에서만 필요)
  const { data: offlineCity, isLoading } = useOfflineCity(tripId);

  // 현재 위치 기능 (Google Maps 모드에서 사용)
  const { moveToCurrentLocation, isLoading: isLocationLoading } = useMyLocation({ mapRef });

  // 지도 영역 자동 조정 (react-native-maps - Google Maps 모드에서만)
  useEffect(() => {
    if (mapRef.current && policy.service.mapProvider === 'google') {
      if (selectedLocation) {
        // 선택된 장소로 포커스
        mapRef.current.animateToRegion({
          latitude: selectedLocation.latitude,
          longitude: selectedLocation.longitude,
