import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { act, renderHook, waitFor } from '@testing-library/react-native';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import apiClient from '@/shared/api/fetcher';
import { useLocationSearch } from '@/features/schedule/create-schedule/useLocationSearch';
import { networkStore, useNetworkStore } from '@/shared/store/network';

jest.mock('@react-native-community/netinfo', () => ({
  __esModule: true,
  default: { addEventListener: jest.fn(), refresh: jest.fn() },
}));
jest.mock('@/shared/api/fetcher', () => ({ __esModule: true, default: { post: jest.fn(), get: jest.fn() } }));
jest.mock('@/shared/hooks/useDebounce', () => ({ useDebounce: (value: unknown) => value }));

const postMock = jest.mocked(apiClient.post);
const getMock = jest.mocked(apiClient.get);
const response = { data: { results: [{ id: 'place', placeId: 'place', name: 'Place', address: 'Address' }] } };
let client: QueryClient;

function Wrapper({ children }: { children: React.ReactNode }) {
  return <QueryClientProvider client={client}>{children}</QueryClientProvider>;
}

beforeEach(() => {
  client = new QueryClient({ defaultOptions: { queries: { retry: false, gcTime: 0 } } });
  useNetworkStore.setState({ realStatus: 'unknown', overrideStatus: null });
  postMock.mockResolvedValue(response);
  getMock.mockResolvedValue({ id: 'place', name: 'Place', address: 'Address', latitude: 1, longitude: 2 });
});

afterEach(() => {
  client.clear();
  networkStore.cleanup();
  jest.restoreAllMocks();
});

describe('장소 검색의 실제 네트워크 요청 경계', () => {
  it.each(['unknown', 'offline'] as const)('강제 online이어도 실제 %s에서는 검색 요청을 시작하지 않는다', async (realStatus) => {
    useNetworkStore.setState({ realStatus, overrideStatus: 'online' });
    const { result } = renderHook(() => useLocationSearch(), { wrapper: Wrapper });
    await act(async () => result.current.handleSearch('Paris'));
    expect(postMock).not.toHaveBeenCalled();
    expect(getMock).not.toHaveBeenCalled();
    expect(result.current.searchQuery).toBe('Paris');
  });

  it('offline 동안 입력과 캐시는 유지하면서 이전 결과의 서비스 접근을 제한한다', async () => {
    useNetworkStore.setState({ realStatus: 'online' });
    const { result } = renderHook(() => useLocationSearch(), { wrapper: Wrapper });
    act(() => result.current.handleSearch('Paris'));
    await waitFor(() => expect(result.current.results).toHaveLength(1));
    const cached = client.getQueryCache().getAll()[0].state.data;
    act(() => useNetworkStore.setState({ realStatus: 'offline' }));
    expect(result.current.results).toEqual([]);
    expect(result.current.searchQuery).toBe('Paris');
    expect(client.getQueryCache().getAll()[0].state.data).toBe(cached);
    expect(postMock).toHaveBeenCalledTimes(1);
  });

  it('검색 전송 뒤 unknown 관측이 오면 후속 상세 요청을 새로 시작하지 않는다', async () => {
    useNetworkStore.setState({ realStatus: 'online' });
    let resolveSearch!: (value: typeof response) => void;
    postMock.mockReturnValueOnce(new Promise((resolve) => { resolveSearch = resolve; }));
    const { result } = renderHook(() => useLocationSearch(), { wrapper: Wrapper });
    act(() => result.current.handleSearch('Paris'));
    await waitFor(() => expect(postMock).toHaveBeenCalledTimes(1));
    await act(async () => {
      useNetworkStore.setState({ realStatus: 'unknown' });
      resolveSearch(response);
    });
    await waitFor(() => expect(client.isFetching()).toBe(0));
    expect(getMock).not.toHaveBeenCalled();
    expect(result.current.searchQuery).toBe('Paris');
  });
});
/**
 * PolicyBasedScheduleMapView - 정책 기반 지도 제공자 선택
 *
 * 정책에 따라 자동으로 지도 제공자를 선택:
 * - online (active/inactive): Google Maps
 * - offline_active: Mapbox (오프라인 지도)
 * - offline_inactive: 지도 사용 불가
 */

import { useAppPolicy } from '@/shared/policy';
import { GoogleScheduleMapView } from './GoogleScheduleMapView';
import { MapboxScheduleMapView } from './MapboxScheduleMapView';
import { MapUnavailableView } from './MapUnavailableView';
import type { ScheduleMapViewProps } from './types';
import { useRealNetworkStatus } from '@/shared/store/network';
import { getOnlineServicePermission } from '@/shared/services/network-access';

/**
 * 정책 기반으로 적절한 지도 제공자를 자동 선택
 * Policy Layer (v3.0)의 service.mapProvider 정책을 따름
 */
export function PolicyBasedScheduleMapView(props: ScheduleMapViewProps) {
  const { tripId, ...mapProps } = props;
  const policy = useAppPolicy(tripId);
  const permission = getOnlineServicePermission(useRealNetworkStatus());

  if (policy.service.mapProvider === 'google' && !permission.allowed) {
    return <MapUnavailableView message={permission.reason} hint='실제 연결이 확인되면 지도를 다시 사용할 수 있어요' />;
  }

  switch (policy.service.mapProvider) {
    case 'google':
      return <GoogleScheduleMapView {...mapProps} tripId={tripId} />;

    case 'mapbox':
      return <MapboxScheduleMapView {...mapProps} tripId={tripId} />;

    case 'none':
      return (
        <MapUnavailableView
          message='오프라인 상태에서는 지도를 사용할 수 없습니다'
          hint='네트워크에 연결하거나 여행을 활성화해주세요'
        />
      );

    default:
      return <MapUnavailableView message='지도를 사용할 수 없어요' />;
  }
}
/**
 * PolicyBasedMapView Component
 * 정책에 따라 Google Maps vs Mapbox 자동 선택
 * Policy Layer (v3.0)의 service.mapProvider 정책을 따름
 */

import { View, Text, StyleSheet } from 'react-native';
import { Search, WifiOff } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { useEffect, useRef } from 'react';
import RNMapView, { Marker, PROVIDER_GOOGLE } from 'react-native-maps';

import { useOfflineCity } from '@/entities/offline-city';
import { useAppPolicy } from '@/shared/policy';
import { OfflineMapView } from './OfflineMapView';
import { useMyLocation } from '@/shared/hooks/map/useMyLocation';
import { MyLocationButton } from '@/shared/components/Map/MyLocationButton';
import { MapUnavailableView } from '@/shared/components/Map/MapUnavailableView';
import { useRealNetworkStatus } from '@/shared/store/network';
import { getOnlineServicePermission } from '@/shared/services/network-access';

interface Location {
  latitude: number;
  longitude: number;
  name: string;
  address: string;
}

interface SmartMapViewProps {
  tripId: string | null;
  locations: Location[];
  selectedLocation: Location | null;
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 32,
  },
  map: {
    flex: 1,
    width: '100%',
  },
});

/**
 * 스마트 지도 컴포넌트
 *
 * 동작 (Policy-Driven):
 * 1. policy.service.mapProvider로 지도 제공자 결정
 *    - 'google': Google Maps (온라인)
 *    - 'mapbox': Mapbox (오프라인 지도)
 *    - 'none': 지도 사용 불가 (offline_inactive)
 * 2. 빈 상태면 검색 유도 UI
 */
export function PolicyBasedMapView({ tripId, locations, selectedLocation }: SmartMapViewProps) {
  const mapRef = useRef<RNMapView>(null);

  // Policy Layer로 지도 제공자 결정
  const policy = useAppPolicy(tripId ?? undefined);
  const permission = getOnlineServicePermission(useRealNetworkStatus());

  // 오프라인 지도 조회 (mapbox 모드에서만 필요)
  const { data: offlineCity, isLoading } = useOfflineCity(tripId);

  // 현재 위치 기능 (Google Maps 모드에서 사용)
  const { moveToCurrentLocation, isLoading: isLocationLoading } = useMyLocation({ mapRef });

  // 지도 영역 자동 조정 (react-native-maps - Google Maps 모드에서만)
  useEffect(() => {
    if (mapRef.current && policy.service.mapProvider === 'google') {
      if (selectedLocation) {
        // 선택된 장소로 포커스
        mapRef.current.animateToRegion({
          latitude: selectedLocation.latitude,
          longitude: selectedLocation.longitude,
          latitudeDelta: 0.01,
          longitudeDelta: 0.01,
        });
      } else if (locations.length > 0) {
        // 여러 검색 결과가 있으면 모두 보이도록
        mapRef.current.fitToCoordinates(
          locations.map((loc) => ({
            latitude: loc.latitude,
            longitude: loc.longitude,
          })),
          {
            edgePadding: { top: 50, right: 50, bottom: 50, left: 50 },
            animated: true,
          },
        );
      }
    }
  }, [locations, selectedLocation, policy.service.mapProvider]);

  if (policy.service.mapProvider === 'google' && !permission.allowed) {
    return <MapUnavailableView message={permission.reason} hint='실제 연결이 확인되면 지도를 다시 사용할 수 있어요' />;
  }

  // 빈 상태
  if (locations.length === 0 && !selectedLocation) {
    return (
      <LinearGradient
        colors={['#E3F2FD', '#E8F5E9']}
        start={{ x: 0, y: 0 }}
        end={{ x: 0, y: 1 }}
        style={styles.container}
      >
        <View className='items-center'>
          <View className='w-24 h-24 rounded-full bg-white/80 items-center justify-center mb-md shadow-sm'>
            <Search size={48} color='#228B22' />
          </View>
          <Text className='text-title-large text-foreground mb-xs'>장소를 검색해주세요</Text>
          <Text className='text-body text-muted-foreground text-center'>방문할 여행지를 찾아보세요</Text>
        </View>
      </LinearGradient>
    );
  }

  // 기본 중심 좌표
  const centerLocation = selectedLocation || locations[0];

  // Policy에 따라 지도 제공자 선택
  switch (policy.service.mapProvider) {
    case 'mapbox':
      // Mapbox 오프라인 지도 사용
      if (offlineCity && !isLoading) {
        console.log('🗺️ Using Mapbox offline map for city:', offlineCity.cityName);
        return <OfflineMapView locations={locations} selectedLocation={selectedLocation} cityId={offlineCity.cityId} />;
      }
      // 오프라인 지도가 아직 다운로드 안 된 경우 로딩 상태
      return (
        <LinearGradient
          colors={['#E3F2FD', '#E8F5E9']}
          start={{ x: 0, y: 0 }}
          end={{ x: 0, y: 1 }}
          style={styles.container}
        >
          <View className='items-center'>
            <Text className='text-title-large text-foreground mb-xs'>오프라인 지도 준비 중...</Text>
            <Text className='text-body text-muted-foreground text-center'>잠시만 기다려주세요</Text>
          </View>
        </LinearGradient>
      );

    case 'none':
      // 지도 사용 불가 (offline_inactive 상태)
      return (
        <LinearGradient
          colors={['#F5F5F5', '#E0E0E0']}
          start={{ x: 0, y: 0 }}
          end={{ x: 0, y: 1 }}
          style={styles.container}
        >
          <View className='items-center'>
            <View className='w-24 h-24 rounded-full bg-white/80 items-center justify-center mb-md shadow-sm'>
              <WifiOff size={48} color='#757575' />
            </View>
            <Text className='text-title-large text-foreground mb-xs'>지도를 사용할 수 없습니다</Text>
            <Text className='text-body text-muted-foreground text-center'>
              오프라인 상태에서는 활성화된 여행만 지도를 볼 수 있어요
            </Text>
          </View>
        </LinearGradient>
      );

    case 'google':
    default:
      // Google Maps 사용 (react-native-maps)
      console.log('🌐 Using Google Maps (online)');
      return (
        <View style={styles.map}>
          <RNMapView
            ref={mapRef}
            provider={PROVIDER_GOOGLE}
            style={styles.map}
            initialRegion={{
              latitude: centerLocation.latitude,
              longitude: centerLocation.longitude,
              latitudeDelta: 0.05,
              longitudeDelta: 0.05,
            }}
            showsUserLocation={true}
            showsMyLocationButton={false} // 기본 버튼 숨김
          >
            {/* 선택된 장소 마커 (큰 마커) */}
            {selectedLocation && (
              <Marker
                coordinate={{
                  latitude: selectedLocation.latitude,
                  longitude: selectedLocation.longitude,
                }}
                title={selectedLocation.name}
                description={selectedLocation.address}
                pinColor='#228B22'
              />
            )}

            {/* 검색 결과 마커들 (선택 전) */}
            {!selectedLocation &&
              locations.map((location, index) => (
                <Marker
                  key={`${location.latitude}-${location.longitude}-${index}`}
                  coordinate={{
                    latitude: location.latitude,
                    longitude: location.longitude,
                  }}
                  title={location.name}
                  description={location.address}
                  pinColor='#228B22'
                />
              ))}
          </RNMapView>

          {/* 커스텀 현재 위치 버튼 */}
          <MyLocationButton
            onPress={moveToCurrentLocation}
            isLoading={isLocationLoading}
            style={{ bottom: 100, right: 16 }} // UI 카드 위로 위치 조정
          />
        </View>
      );
  }
}

