import React, { createContext, useContext, useEffect, useRef, useState, useCallback } from 'react';
import { networkStore, useNetworkStore, useRealNetworkStatus } from '@/shared/store/network';
import { authStore, useAuthStore } from '@/shared/store/auth';
import { syncData } from './engine';

export type SyncRunResult =
  | { status: 'completed'; message: string }
  | { status: 'failed'; message: string }
  | { status: 'blocked'; message: string };

interface SyncContextValue {
  isSyncing: boolean;
  lastSyncedAt: Date | null;
  triggerManualSync: () => Promise<SyncRunResult>;
}

const SyncContext = createContext<SyncContextValue | undefined>(undefined);

export function useSyncContext() {
  const context = useContext(SyncContext);
  if (!context) {
    throw new Error('useSyncContext must be used within SyncProvider');
  }
  return context;
}

interface SyncProviderProps {
  children: React.ReactNode;
  isDatabaseReady: boolean;
  enablePeriodicSync?: boolean;
  syncInterval?: number;
}

export function SyncProvider({
  children,
  isDatabaseReady,
  enablePeriodicSync = false,
  syncInterval = 5 * 60 * 1000,
}: SyncProviderProps) {
  const networkStatus = useRealNetworkStatus();
  const overrideStatus = useNetworkStore((state) => state.overrideStatus);
  const isAuthInitialized = useAuthStore((state) => state.isInitialized);
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const canSync =
    isDatabaseReady && isAuthInitialized && isAuthenticated && networkStatus === 'online' && overrideStatus === null;

  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
  const inFlightRef = useRef<Promise<SyncRunResult> | null>(null);
  const databaseReadyRef = useRef(isDatabaseReady);
  databaseReadyRef.current = isDatabaseReady;
  const previouslyEligibleRef = useRef(false);

  const executeSync = useCallback((): Promise<SyncRunResult> => {
    // 이전 render의 callback과 자동/수동 호출도 같은 진행 중 실행을 기다린다.
    if (inFlightRef.current) {
      return inFlightRef.current;
    }

    let blockedMessage: string | null = null;
    if (!databaseReadyRef.current) {
      blockedMessage = '데이터베이스가 준비되지 않아 동기화할 수 없습니다.';
    } else if (!authStore.isInitialized || !authStore.isAuthenticated) {
      blockedMessage = '로그인 준비가 완료된 뒤 동기화할 수 있습니다.';
    } else if (networkStore.override !== null) {
      blockedMessage = '네트워크 강제 설정 중에는 동기화할 수 없습니다. 실제 상태로 되돌려 주세요.';
    } else if (networkStore.realStatus !== 'online') {
      blockedMessage = '인터넷 연결이 확인된 뒤 동기화할 수 있습니다.';
    }
    if (blockedMessage) {
      return Promise.resolve({ status: 'blocked', message: blockedMessage });
    }

    let resolveRun!: (result: SyncRunResult) => void;
    const run = new Promise<SyncRunResult>((resolve) => {
      resolveRun = resolve;
    });
    // React 표시 상태를 갱신하기 전에 실행 소유권을 선점한다.
    inFlightRef.current = run;
    previouslyEligibleRef.current = true;
    setIsSyncing(true);

    (async () => {
      let result: SyncRunResult;
      try {
        await syncData();
        setLastSyncedAt(new Date());
        // engine가 반환됐음을 뜻한다. queue 전체 반영 여부는 engine의 결과 계약에 따른다.
        result = { status: 'completed', message: '동기화가 완료되었습니다.' };
      } catch {
        result = { status: 'failed', message: '동기화에 실패했습니다.' };
      }
      inFlightRef.current = null;
      setIsSyncing(false);
      resolveRun(result);
    })();

    return run;
  }, []);

  // 최초 준비 완료, 로그인, 연결 복구, 강제 설정 해제가 같은 시작 경계를 사용한다.
  useEffect(() => {
    const wasEligible = previouslyEligibleRef.current;
    previouslyEligibleRef.current = canSync;
    if (canSync && !wasEligible) {
      executeSync();
    }
  }, [canSync, executeSync]);

  useEffect(() => {
    if (!enablePeriodicSync) {
      return;
    }
    const intervalId = setInterval(() => {
      executeSync();
    }, syncInterval);
    return () => clearInterval(intervalId);
  }, [enablePeriodicSync, syncInterval, executeSync]);

  return (
    <SyncContext.Provider value={{ isSyncing, lastSyncedAt, triggerManualSync: executeSync }}>
      {children}
    </SyncContext.Provider>
  );
}
import { View, ActivityIndicator, Text, Keyboard } from 'react-native';
import { useState } from 'react';
import { ArrowLeft } from 'lucide-react-native';
import { router, useLocalSearchParams } from 'expo-router';
import { MobileHeader, DatePicker, TimePicker, PolicyBasedMapView, PolicyErrorDisplay } from '@/shared/components';
import { useStep } from '@/shared/hooks/useStep';
import {
  useCreateScheduleForm,
  useLocationSearch,
  LocationSearchBar,
  LocationSearchResults,
  ScheduleForm,
  ManualScheduleForm,
  type Location,
} from '@/features/schedule/create-schedule';
import { useGetTrips, type TripResponse } from '@/entities/trip';
import { useAppPolicy } from '@/shared/policy';

const STEPS = {
  SEARCH: 1, // 장소 검색 단계
  FORM: 2, // 일정 입력 폼 단계
} as const;

export default function CreateScheduleScreen() {
  const params = useLocalSearchParams<{ tripId?: string; date?: string }>();
  const tripId = params.tripId || '';
  const prefilledDate = params.date;

  // Trip 정보 조회
  const { data: tripsData, isLoading: isLoadingTrips } = useGetTrips();
  const currentTrip = tripsData?.find((trip: TripResponse) => trip.id === tripId);

  // ✅ Policy 체크: 모든 정책 조회
  const policy = useAppPolicy(tripId);

  // 단계 관리
  const { currentStep, goToNextStep, goToPrevStep } = useStep({
    initialStep: STEPS.SEARCH,
    maxStep: STEPS.FORM,
  });

  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null);

  // 여행 도시 정보를 검색에 전달
  const cityContext = currentTrip
    ? {
        cityName: currentTrip.destination,
        latitude: currentTrip.latitude ? parseFloat(currentTrip.latitude) : undefined,
        longitude: currentTrip.longitude ? parseFloat(currentTrip.longitude) : undefined,
      }
    : undefined;

  const { searchQuery, results, isSearching, handleSearch, clearSearch } = useLocationSearch(cityContext);

  const {
    form,
    isPending,
    datePickerVisible,
    timePickerVisible,
    handleShowTimePicker,
    handleSelectDate,
    handleSelectTime,
    onSubmit,
  } = useCreateScheduleForm({
    tripId,
    selectedLocation,
    onSuccess: () => {
      if (router.canGoBack()) {
        router.back();
      } else {
        router.replace('/(tabs)/schedule');
      }
    },
  });

  const { watch } = form;

  // prefilledDate가 있으면 초기값으로 설정
  if (prefilledDate && !watch('date')) {
    form.setValue('date', prefilledDate);
  }

  const handleBackPress = () => {
    if (currentStep === STEPS.FORM) {
      handleClearLocation();
      return;
    }

    if (router.canGoBack()) {
      router.back();
    } else {
      router.replace('/(tabs)/schedule');
    }
  };

  const handleSelectLocation = (location: Location) => {
    Keyboard.dismiss();
    setSelectedLocation(location);
    // clearSearch(); // 검색 결과를 바로 지우지 않도록 주석 처리
    goToNextStep(); // 검색 → 폼 단계로 이동
  };

  const handleClearLocation = () => {
    setSelectedLocation(null);
    form.reset();
    goToPrevStep(); // 폼 → 검색 단계로 이동
  };

  const handleCancel = () => {
    handleClearLocation();
  };

  // Trip 로딩 중
  if (isLoadingTrips) {
    return (
      <View className='flex-1 bg-background'>
        <MobileHeader
          title='새 일정 추가'
          leftIcon={<ArrowLeft size={20} color='#1F1F1F' />}
          onLeftPress={handleBackPress}
        />
        <View className='flex-1 items-center justify-center px-sm'>
          <ActivityIndicator size='large' color='#228B22' />
          <Text className='text-body text-muted-foreground mt-md'>여행 정보 불러오는 중...</Text>
        </View>
      </View>
    );
  }

  return (
    <View className='flex-1 bg-background'>
      {/* Header */}
      <MobileHeader
        title='새 일정 추가'
        leftIcon={<ArrowLeft size={20} color='#1F1F1F' />}
        onLeftPress={handleBackPress}
      />

      {!policy.schedule.create.allowed && <PolicyErrorDisplay permission={policy.schedule.create} variant='banner' />}

      {/* 검색창 (검색 단계에만 표시) */}
      {/* ⚠️ Policy: manual-only mode에서는 검색창 숨김 */}
      {currentStep === STEPS.SEARCH && policy.service.searchMode === 'api' && (
        <LocationSearchBar value={searchQuery} onChangeText={handleSearch} onClear={clearSearch} autoFocus />
      )}

      {/* ⚠️ Policy: manual-only mode 안내 메시지 */}
      {policy.schedule.create.mode === 'manual-only' && (
        <PolicyErrorDisplay permission={policy.schedule.create} variant='banner' />
      )}

      {/* 지도 영역 + 결과/폼 */}
      <View className='flex-1 relative' onTouchStart={() => Keyboard.dismiss()}>
        <PolicyBasedMapView tripId={tripId} locations={results} selectedLocation={selectedLocation} />

        {/* 검색 결과 리스트 (검색 단계 + 검색 중이거나 결과 있을 때) */}
        {/* ⚠️ Policy: manual-only mode에서는 검색 결과 숨김 */}
        {currentStep === STEPS.SEARCH && policy.service.searchMode === 'api' && (isSearching || results.length > 0) && (
          <LocationSearchResults results={results} onSelectLocation={handleSelectLocation} isSearching={isSearching} />
        )}

        {/* 일정 입력 폼 (폼 단계일 때) */}
        {currentStep === STEPS.FORM && selectedLocation && (
          <ScheduleForm
            selectedLocation={selectedLocation}
            form={form}
            onClearLocation={handleClearLocation}
            onShowTimePicker={handleShowTimePicker}
            onSubmit={onSubmit}
            onCancel={handleCancel}
            isPending={isPending}
          />
        )}

        {/* 장소 선택 전에도 입력 가능하며, 네트워크 변화로 폼을 교체하지 않는다. */}
        {!(currentStep === STEPS.FORM && selectedLocation) && (
          <ManualScheduleForm
            form={form}
            onShowTimePicker={handleShowTimePicker}
            onSubmit={onSubmit}
            onCancel={handleBackPress}
            isPending={isPending}
          />
        )}
      </View>

      {/* 날짜와 시간 입력은 네트워크 변화에도 유지한다. */}
      <DatePicker
        visible={datePickerVisible}
        onClose={() => handleSelectDate(watch('date') || '')}
        onSelectDate={handleSelectDate}
      />

      <TimePicker
        visible={timePickerVisible}
        onClose={() => handleSelectTime(watch('time') || '09:00')}
        onSelectTime={handleSelectTime}
        initialTime={watch('time') || '09:00'}
      />
    </View>
  );
}
